var largestInteger = function(num) {
    const s = String(num);
    const evens = [];
    const odds = [];
    for (const c of s) {
        if (Number(c) % 2 === 0) evens.push(c);
        else odds.push(c);
    }
    evens.sort((a, b) => b.localeCompare(a));
    odds.sort((a, b) => b.localeCompare(a));
    let ei = 0, oi = 0;
    let res = '';
    for (const c of s) {
        if (Number(c) % 2 === 0) res += evens[ei++];
        else res += odds[oi++];
    }
    return Number(res);
};
